-- Errata reading for L07: Obesity = computed BMI >= 30 (vitals height, latest weight); prediabetes and diabetes as the reference.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions')), c AS (SELECT patient, json_extract(payload,'$.description') d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM r WHERE stream='conditions'), bht AS MATERIALIZED (SELECT patient, max(json_extract(payload,'$.value')) h FROM records WHERE stream='vitals' AND json_extract(payload,'$.measurement')='height_cm' GROUP BY 1), bdw AS MATERIALIZED (SELECT patient, json_extract(payload,'$.event_date')||coalesce(json_extract(payload,'$.event_time'),'') k, json_extract(payload,'$.weight_kg') w FROM records WHERE stream='vitals' AND json_extract(payload,'$.weight_kg') IS NOT NULL AND json_extract(payload,'$.event_date') IS NOT NULL), blw AS MATERIALIZED (SELECT bdw.patient, max(bdw.w) w FROM bdw JOIN (SELECT patient, max(k) mk FROM bdw GROUP BY 1) m ON m.patient=bdw.patient AND m.mk=bdw.k GROUP BY 1), bbw AS MATERIALIZED (SELECT patient, max(json_extract(payload,'$.value')) w FROM records WHERE stream='vitals' AND json_extract(payload,'$.measurement')='weight_kg' GROUP BY 1), bmi AS MATERIALIZED (SELECT bht.patient FROM bht LEFT JOIN blw ON blw.patient=bht.patient LEFT JOIN bbw ON bbw.patient=bht.patient WHERE coalesce(blw.w, bbw.w) / ((bht.h/100.0)*(bht.h/100.0)) >= 30), ob AS (SELECT patient FROM bmi), pre AS (SELECT DISTINCT patient FROM c WHERE s='714628002' OR i='R73.03' OR lower(d) LIKE '%prediabetes%'), dm AS (SELECT DISTINCT patient FROM c WHERE (substr(i,1,3) IN ('E10','E11','E13') OR s='44054006' OR (lower(d) LIKE '%diabetes mellitus%' AND lower(d) NOT LIKE 'family history%') OR d LIKE '%T1DM%' OR d LIKE '%T2DM%')) SELECT COUNT(*) AS count FROM ob WHERE patient IN (SELECT patient FROM pre) AND patient NOT IN (SELECT patient FROM dm);
